BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"f19286fd-2101-4e99-969f-2de0773536ab","n":1,"title":"الاستماع","passage":"موضوع الوحدة «أمراض العصر». في نشاط توعوي مدرسي تناقش مجموعة أهمية الحصول على المعلومات الصحية من جهات معتمدة، ومراعاة خصوصية الأشخاص والابتعاد عن التشخيص الذاتي. تدون المجموعة ثلاث أسئلة تريد طرحها على مختص، وتفصل بين الوقاية العامة والنصيحة الطبية الفردية. المهارة: الاستماع. يُقرأ النص التدريبي بصوت واضح أو يعرض عبر خاصية الاستماع؛ يدون المتعلم الفكرة وتفصيلين سمعهما، ثم يقارن ما سمع بما فهم دون إضافة معلومات لم ترد. يلتزم المعلم بتيسير الإعادة وإتاحة النص المكتوب للمتعلمين عند الحاجة.","question":"ما الفكرة الرئيسة التي يجب التقاطها من الاستماع إلى نص «أمراض العصر»؟","correct":"فحص المصادر الصحية ومراعاة الخصوصية","wrong":["تشخيص زميل دون مختص","نشر معلومات شخصية","الاعتماد على الشائعة"],"practice":"استمع إلى النص الأصلي التدريبي مرتين، وسجل المصدر الصحي وتفصيلين داعمين ومعلومة تحتاج تحققًا.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"f19286fd-2101-4e99-969f-2de0773536ab","n":2,"title":"التحدث","passage":"موضوع الوحدة «أمراض العصر». في نشاط توعوي مدرسي تناقش مجموعة أهمية الحصول على المعلومات الصحية من جهات معتمدة، ومراعاة خصوصية الأشخاص والابتعاد عن التشخيص الذاتي. تدون المجموعة ثلاث أسئلة تريد طرحها على مختص، وتفصل بين الوقاية العامة والنصيحة الطبية الفردية. المهارة: التحدث. يبدأ المتحدث بمقدمة محددة ويعرض رأيه مدعومًا بشاهد أو مثال، ثم يتيح للآخرين طرح الأسئلة ويعترف بما لم يتحقق منه. في التدريب يتكلم الطالب دقيقة واحدة عن موضوع الوحدة ويبتعد عن التعميم وأحكام الأشخاص.","question":"أي خطة مناسبة لتقديم حديث قصير حول «أمراض العصر»؟","correct":"الحديث عن الوقاية بمعلومات عامة","wrong":["رفع الصوت بلا حجة","تكرار شعار دون دليل","تجنب أسئلة الجمهور"],"practice":"قدم عرضًا شفهيًا لمدة دقيقة عن «أمراض العصر» يتضمن فكرة وشاهدًا وسؤالًا يجيب عنه زميل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"f19286fd-2101-4e99-969f-2de0773536ab","n":3,"title":"القراءة","passage":"موضوع الوحدة «أمراض العصر». في نشاط توعوي مدرسي تناقش مجموعة أهمية الحصول على المعلومات الصحية من جهات معتمدة، ومراعاة خصوصية الأشخاص والابتعاد عن التشخيص الذاتي. تدون المجموعة ثلاث أسئلة تريد طرحها على مختص، وتفصل بين الوقاية العامة والنصيحة الطبية الفردية. المهارة: القراءة. يحدد المتعلم الفكرة في الفقرة ثم يستخرج دليلًا من النص ويشرح علاقة السبب بالنتيجة أو قيمة القرار الموصوف. يفصل بين ما تقوله الفقرة وما قد يضيفه من معرفته، ويضع علامة على كل معلومة لا تكفي البيانات لتقريرها.","question":"أي عبارة تلخص رسالة فقرة «أمراض العصر»؟","correct":"فحص المصادر الصحية ومراعاة الخصوصية","wrong":["تشخيص زميل دون مختص","نشر معلومات شخصية","الاعتماد على الشائعة"],"practice":"اقرأ النص التدريبي وحدد الجملة الدالة على المصدر الصحي، ثم اكتب تفسيرًا لا يتجاوز ما ورد.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"f19286fd-2101-4e99-969f-2de0773536ab","n":4,"title":"الكتابة","passage":"موضوع الوحدة «أمراض العصر». في نشاط توعوي مدرسي تناقش مجموعة أهمية الحصول على المعلومات الصحية من جهات معتمدة، ومراعاة خصوصية الأشخاص والابتعاد عن التشخيص الذاتي. تدون المجموعة ثلاث أسئلة تريد طرحها على مختص، وتفصل بين الوقاية العامة والنصيحة الطبية الفردية. المهارة: الكتابة. تتضمن الفقرة الكتابية جملة موضوعية وشرحًا وشاهدًا أو موقفًا وخاتمة توضح الموقف. تُراجع الأخطاء الإملائية والروابط، مع التنبيه إلى أن نصوص ضاديوم أمثلة أصلية لا تطابق بالضرورة صفحات الكتاب الوزاري.","question":"ما الذي يجعل فقرة عن «أمراض العصر» مقنعة ومترابطة؟","correct":"فكرة واضحة وشاهد صحيح ومراجعة الصياغة","wrong":["جمع كلمات بلا ترتيب","اختلاق مصدر لزيادة الإقناع","نسخ عنوان الموضوع مرات"],"practice":"اكتب فقرة من ست جمل حول «أمراض العصر» تتضمن موقفًا أصليًا وشاهدًا ورابطًا بين الجمل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"f19286fd-2101-4e99-969f-2de0773536ab","n":5,"title":"أبني لغتي","passage":"موضوع الوحدة «أمراض العصر». في نشاط توعوي مدرسي تناقش مجموعة أهمية الحصول على المعلومات الصحية من جهات معتمدة، ومراعاة خصوصية الأشخاص والابتعاد عن التشخيص الذاتي. تدون المجموعة ثلاث أسئلة تريد طرحها على مختص، وتفصل بين الوقاية العامة والنصيحة الطبية الفردية. المهارة: أبني لغتي. يُميز المتعلم في الجملة الاسمية المبتدأ والخبر ويتابع وظيفة النعت أو شبه الجملة إذا وردت، ويدرس علامات الإعراب من سياقها. تستعمل أمثلة جديدة مستقلة عن النص الوزاري، ثم يكتب الطالب صياغة صحيحة في موضوع الوحدة.","question":"ما إعراب الكلمة الأولى في المثال «المعلوماتُ موثوقةٌ عندما تُراجع مصادرها»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","حال منصوبة","مضاف إليه مجرور"],"practice":"حلل المبتدأ والخبر في «المعلوماتُ موثوقةٌ عندما تُراجع مصادرها»، ثم اكتب جملتين اسميتين أخريين عن المصدر الصحي.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"05584f78-0938-46dc-9fc2-4461a6368c83","n":1,"title":"الاستماع","passage":"موضوع الوحدة «التعليم التقني بوابة المستقبل». تعرّف الطلاب إلى مشروع صغير لتصميم وسيلة تعليمية، فقسّموا المهام بين البرمجة والتجريب وكتابة التقرير. بعد اختبار أولي اكتشفوا خطأ في أداة الحساب، فسجلوا المشكلة قبل تعديل النموذج بدل الادعاء أن كل شيء يعمل. المهارة: الاستماع. يُقرأ النص التدريبي بصوت واضح أو يعرض عبر خاصية الاستماع؛ يدون المتعلم الفكرة وتفصيلين سمعهما، ثم يقارن ما سمع بما فهم دون إضافة معلومات لم ترد. يلتزم المعلم بتيسير الإعادة وإتاحة النص المكتوب للمتعلمين عند الحاجة.","question":"ما الفكرة الرئيسة التي يجب التقاطها من الاستماع إلى نص «التعليم التقني بوابة المستقبل»؟","correct":"اختبار النموذج وتوثيق الأخطاء والتعاون","wrong":["إخفاء فشل الاختبار","نقل المنتج دون مراجعة","رفض تقسيم المهام"],"practice":"استمع إلى النص الأصلي التدريبي مرتين، وسجل التجريب وتفصيلين داعمين ومعلومة تحتاج تحققًا.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"05584f78-0938-46dc-9fc2-4461a6368c83","n":2,"title":"التحدث","passage":"موضوع الوحدة «التعليم التقني بوابة المستقبل». تعرّف الطلاب إلى مشروع صغير لتصميم وسيلة تعليمية، فقسّموا المهام بين البرمجة والتجريب وكتابة التقرير. بعد اختبار أولي اكتشفوا خطأ في أداة الحساب، فسجلوا المشكلة قبل تعديل النموذج بدل الادعاء أن كل شيء يعمل. المهارة: التحدث. يبدأ المتحدث بمقدمة محددة ويعرض رأيه مدعومًا بشاهد أو مثال، ثم يتيح للآخرين طرح الأسئلة ويعترف بما لم يتحقق منه. في التدريب يتكلم الطالب دقيقة واحدة عن موضوع الوحدة ويبتعد عن التعميم وأحكام الأشخاص.","question":"أي خطة مناسبة لتقديم حديث قصير حول «التعليم التقني بوابة المستقبل»؟","correct":"عرض فكرة تقنية مع نتيجة قابلة للتحقق","wrong":["رفع الصوت بلا حجة","تكرار شعار دون دليل","تجنب أسئلة الجمهور"],"practice":"قدم عرضًا شفهيًا لمدة دقيقة عن «التعليم التقني بوابة المستقبل» يتضمن فكرة وشاهدًا وسؤالًا يجيب عنه زميل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"05584f78-0938-46dc-9fc2-4461a6368c83","n":3,"title":"القراءة","passage":"موضوع الوحدة «التعليم التقني بوابة المستقبل». تعرّف الطلاب إلى مشروع صغير لتصميم وسيلة تعليمية، فقسّموا المهام بين البرمجة والتجريب وكتابة التقرير. بعد اختبار أولي اكتشفوا خطأ في أداة الحساب، فسجلوا المشكلة قبل تعديل النموذج بدل الادعاء أن كل شيء يعمل. المهارة: القراءة. يحدد المتعلم الفكرة في الفقرة ثم يستخرج دليلًا من النص ويشرح علاقة السبب بالنتيجة أو قيمة القرار الموصوف. يفصل بين ما تقوله الفقرة وما قد يضيفه من معرفته، ويضع علامة على كل معلومة لا تكفي البيانات لتقريرها.","question":"أي عبارة تلخص رسالة فقرة «التعليم التقني بوابة المستقبل»؟","correct":"اختبار النموذج وتوثيق الأخطاء والتعاون","wrong":["إخفاء فشل الاختبار","نقل المنتج دون مراجعة","رفض تقسيم المهام"],"practice":"اقرأ النص التدريبي وحدد الجملة الدالة على التجريب، ثم اكتب تفسيرًا لا يتجاوز ما ورد.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"05584f78-0938-46dc-9fc2-4461a6368c83","n":4,"title":"الكتابة","passage":"موضوع الوحدة «التعليم التقني بوابة المستقبل». تعرّف الطلاب إلى مشروع صغير لتصميم وسيلة تعليمية، فقسّموا المهام بين البرمجة والتجريب وكتابة التقرير. بعد اختبار أولي اكتشفوا خطأ في أداة الحساب، فسجلوا المشكلة قبل تعديل النموذج بدل الادعاء أن كل شيء يعمل. المهارة: الكتابة. تتضمن الفقرة الكتابية جملة موضوعية وشرحًا وشاهدًا أو موقفًا وخاتمة توضح الموقف. تُراجع الأخطاء الإملائية والروابط، مع التنبيه إلى أن نصوص ضاديوم أمثلة أصلية لا تطابق بالضرورة صفحات الكتاب الوزاري.","question":"ما الذي يجعل فقرة عن «التعليم التقني بوابة المستقبل» مقنعة ومترابطة؟","correct":"فكرة واضحة وشاهد صحيح ومراجعة الصياغة","wrong":["جمع كلمات بلا ترتيب","اختلاق مصدر لزيادة الإقناع","نسخ عنوان الموضوع مرات"],"practice":"اكتب فقرة من ست جمل حول «التعليم التقني بوابة المستقبل» تتضمن موقفًا أصليًا وشاهدًا ورابطًا بين الجمل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"05584f78-0938-46dc-9fc2-4461a6368c83","n":5,"title":"أبني لغتي","passage":"موضوع الوحدة «التعليم التقني بوابة المستقبل». تعرّف الطلاب إلى مشروع صغير لتصميم وسيلة تعليمية، فقسّموا المهام بين البرمجة والتجريب وكتابة التقرير. بعد اختبار أولي اكتشفوا خطأ في أداة الحساب، فسجلوا المشكلة قبل تعديل النموذج بدل الادعاء أن كل شيء يعمل. المهارة: أبني لغتي. يُميز المتعلم في الجملة الاسمية المبتدأ والخبر ويتابع وظيفة النعت أو شبه الجملة إذا وردت، ويدرس علامات الإعراب من سياقها. تستعمل أمثلة جديدة مستقلة عن النص الوزاري، ثم يكتب الطالب صياغة صحيحة في موضوع الوحدة.","question":"ما إعراب الكلمة الأولى في المثال «المهارةُ التقنيةُ نافعةٌ حين يُحسن صاحبها استعمالها»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","حال منصوبة","مضاف إليه مجرور"],"practice":"حلل المبتدأ والخبر في «المهارةُ التقنيةُ نافعةٌ حين يُحسن صاحبها استعمالها»، ثم اكتب جملتين اسميتين أخريين عن التجريب.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"e6106e2d-9972-4e6f-ad21-035231c17450","n":1,"title":"الاستماع","passage":"موضوع الوحدة «في حب الوطن». اختارت مجموعة من الطلاب خدمة حديقة عامة بالتنسيق مع الجهة المختصة، فوضعت خطة تحافظ على سلامة المشاركين وحق السكان في استخدام المكان. بعد النشاط كتبوا ما أنجزوه فعلًا وما يحتاج متابعة دون اختراع أرقام للنجاح. المهارة: الاستماع. يُقرأ النص التدريبي بصوت واضح أو يعرض عبر خاصية الاستماع؛ يدون المتعلم الفكرة وتفصيلين سمعهما، ثم يقارن ما سمع بما فهم دون إضافة معلومات لم ترد. يلتزم المعلم بتيسير الإعادة وإتاحة النص المكتوب للمتعلمين عند الحاجة.","question":"ما الفكرة الرئيسة التي يجب التقاطها من الاستماع إلى نص «في حب الوطن»؟","correct":"خدمة المرافق المشتركة باحترام ومسؤولية","wrong":["إتلاف المكان","منع الزوار","اختلاق النتائج"],"practice":"استمع إلى النص الأصلي التدريبي مرتين، وسجل المسؤولية وتفصيلين داعمين ومعلومة تحتاج تحققًا.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"e6106e2d-9972-4e6f-ad21-035231c17450","n":2,"title":"التحدث","passage":"موضوع الوحدة «في حب الوطن». اختارت مجموعة من الطلاب خدمة حديقة عامة بالتنسيق مع الجهة المختصة، فوضعت خطة تحافظ على سلامة المشاركين وحق السكان في استخدام المكان. بعد النشاط كتبوا ما أنجزوه فعلًا وما يحتاج متابعة دون اختراع أرقام للنجاح. المهارة: التحدث. يبدأ المتحدث بمقدمة محددة ويعرض رأيه مدعومًا بشاهد أو مثال، ثم يتيح للآخرين طرح الأسئلة ويعترف بما لم يتحقق منه. في التدريب يتكلم الطالب دقيقة واحدة عن موضوع الوحدة ويبتعد عن التعميم وأحكام الأشخاص.","question":"أي خطة مناسبة لتقديم حديث قصير حول «في حب الوطن»؟","correct":"وصف عمل مجتمعي إيجابي بالأدلة","wrong":["رفع الصوت بلا حجة","تكرار شعار دون دليل","تجنب أسئلة الجمهور"],"practice":"قدم عرضًا شفهيًا لمدة دقيقة عن «في حب الوطن» يتضمن فكرة وشاهدًا وسؤالًا يجيب عنه زميل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"e6106e2d-9972-4e6f-ad21-035231c17450","n":3,"title":"القراءة","passage":"موضوع الوحدة «في حب الوطن». اختارت مجموعة من الطلاب خدمة حديقة عامة بالتنسيق مع الجهة المختصة، فوضعت خطة تحافظ على سلامة المشاركين وحق السكان في استخدام المكان. بعد النشاط كتبوا ما أنجزوه فعلًا وما يحتاج متابعة دون اختراع أرقام للنجاح. المهارة: القراءة. يحدد المتعلم الفكرة في الفقرة ثم يستخرج دليلًا من النص ويشرح علاقة السبب بالنتيجة أو قيمة القرار الموصوف. يفصل بين ما تقوله الفقرة وما قد يضيفه من معرفته، ويضع علامة على كل معلومة لا تكفي البيانات لتقريرها.","question":"أي عبارة تلخص رسالة فقرة «في حب الوطن»؟","correct":"خدمة المرافق المشتركة باحترام ومسؤولية","wrong":["إتلاف المكان","منع الزوار","اختلاق النتائج"],"practice":"اقرأ النص التدريبي وحدد الجملة الدالة على المسؤولية، ثم اكتب تفسيرًا لا يتجاوز ما ورد.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"e6106e2d-9972-4e6f-ad21-035231c17450","n":4,"title":"الكتابة","passage":"موضوع الوحدة «في حب الوطن». اختارت مجموعة من الطلاب خدمة حديقة عامة بالتنسيق مع الجهة المختصة، فوضعت خطة تحافظ على سلامة المشاركين وحق السكان في استخدام المكان. بعد النشاط كتبوا ما أنجزوه فعلًا وما يحتاج متابعة دون اختراع أرقام للنجاح. المهارة: الكتابة. تتضمن الفقرة الكتابية جملة موضوعية وشرحًا وشاهدًا أو موقفًا وخاتمة توضح الموقف. تُراجع الأخطاء الإملائية والروابط، مع التنبيه إلى أن نصوص ضاديوم أمثلة أصلية لا تطابق بالضرورة صفحات الكتاب الوزاري.","question":"ما الذي يجعل فقرة عن «في حب الوطن» مقنعة ومترابطة؟","correct":"فكرة واضحة وشاهد صحيح ومراجعة الصياغة","wrong":["جمع كلمات بلا ترتيب","اختلاق مصدر لزيادة الإقناع","نسخ عنوان الموضوع مرات"],"practice":"اكتب فقرة من ست جمل حول «في حب الوطن» تتضمن موقفًا أصليًا وشاهدًا ورابطًا بين الجمل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"e6106e2d-9972-4e6f-ad21-035231c17450","n":5,"title":"أبني لغتي","passage":"موضوع الوحدة «في حب الوطن». اختارت مجموعة من الطلاب خدمة حديقة عامة بالتنسيق مع الجهة المختصة، فوضعت خطة تحافظ على سلامة المشاركين وحق السكان في استخدام المكان. بعد النشاط كتبوا ما أنجزوه فعلًا وما يحتاج متابعة دون اختراع أرقام للنجاح. المهارة: أبني لغتي. يُميز المتعلم في الجملة الاسمية المبتدأ والخبر ويتابع وظيفة النعت أو شبه الجملة إذا وردت، ويدرس علامات الإعراب من سياقها. تستعمل أمثلة جديدة مستقلة عن النص الوزاري، ثم يكتب الطالب صياغة صحيحة في موضوع الوحدة.","question":"ما إعراب الكلمة الأولى في المثال «الوطنُ بيتٌ يشترك الناس في رعايته»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","حال منصوبة","مضاف إليه مجرور"],"practice":"حلل المبتدأ والخبر في «الوطنُ بيتٌ يشترك الناس في رعايته»، ثم اكتب جملتين اسميتين أخريين عن المسؤولية.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"0a27f75b-3990-4fdb-add8-aae01ae2bef6","n":1,"title":"الاستماع","passage":"موضوع الوحدة «من القيم الإنسانية في القرآن الكريم». تناقش حصة اللغة العربية قيم الصدق والعدل والإحسان بوصفها مفاهيم أخلاقية تحتاج إلى دراسة النص القرآني من المصحف الصحيح عند الاستشهاد. وفي مثال تدريبي مستقل يعيد طالب كتابًا وجدَه إلى صاحبه ويحترم حق الآخرين في السؤال. المهارة: الاستماع. يُقرأ النص التدريبي بصوت واضح أو يعرض عبر خاصية الاستماع؛ يدون المتعلم الفكرة وتفصيلين سمعهما، ثم يقارن ما سمع بما فهم دون إضافة معلومات لم ترد. يلتزم المعلم بتيسير الإعادة وإتاحة النص المكتوب للمتعلمين عند الحاجة.","question":"ما الفكرة الرئيسة التي يجب التقاطها من الاستماع إلى نص «من القيم الإنسانية في القرآن الكريم»؟","correct":"التحقق من الآية واحترام قيم الصدق والعدل","wrong":["اختلاق آية مناسبة","تغيير نص آية","نسبة قصة تدريبية للقرآن"],"practice":"استمع إلى النص الأصلي التدريبي مرتين، وسجل الصدق وتفصيلين داعمين ومعلومة تحتاج تحققًا.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"0a27f75b-3990-4fdb-add8-aae01ae2bef6","n":2,"title":"التحدث","passage":"موضوع الوحدة «من القيم الإنسانية في القرآن الكريم». تناقش حصة اللغة العربية قيم الصدق والعدل والإحسان بوصفها مفاهيم أخلاقية تحتاج إلى دراسة النص القرآني من المصحف الصحيح عند الاستشهاد. وفي مثال تدريبي مستقل يعيد طالب كتابًا وجدَه إلى صاحبه ويحترم حق الآخرين في السؤال. المهارة: التحدث. يبدأ المتحدث بمقدمة محددة ويعرض رأيه مدعومًا بشاهد أو مثال، ثم يتيح للآخرين طرح الأسئلة ويعترف بما لم يتحقق منه. في التدريب يتكلم الطالب دقيقة واحدة عن موضوع الوحدة ويبتعد عن التعميم وأحكام الأشخاص.","question":"أي خطة مناسبة لتقديم حديث قصير حول «من القيم الإنسانية في القرآن الكريم»؟","correct":"مناقشة قيمة أخلاقية دون تحريف النص الديني","wrong":["رفع الصوت بلا حجة","تكرار شعار دون دليل","تجنب أسئلة الجمهور"],"practice":"قدم عرضًا شفهيًا لمدة دقيقة عن «من القيم الإنسانية في القرآن الكريم» يتضمن فكرة وشاهدًا وسؤالًا يجيب عنه زميل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"0a27f75b-3990-4fdb-add8-aae01ae2bef6","n":3,"title":"القراءة","passage":"موضوع الوحدة «من القيم الإنسانية في القرآن الكريم». تناقش حصة اللغة العربية قيم الصدق والعدل والإحسان بوصفها مفاهيم أخلاقية تحتاج إلى دراسة النص القرآني من المصحف الصحيح عند الاستشهاد. وفي مثال تدريبي مستقل يعيد طالب كتابًا وجدَه إلى صاحبه ويحترم حق الآخرين في السؤال. المهارة: القراءة. يحدد المتعلم الفكرة في الفقرة ثم يستخرج دليلًا من النص ويشرح علاقة السبب بالنتيجة أو قيمة القرار الموصوف. يفصل بين ما تقوله الفقرة وما قد يضيفه من معرفته، ويضع علامة على كل معلومة لا تكفي البيانات لتقريرها.","question":"أي عبارة تلخص رسالة فقرة «من القيم الإنسانية في القرآن الكريم»؟","correct":"التحقق من الآية واحترام قيم الصدق والعدل","wrong":["اختلاق آية مناسبة","تغيير نص آية","نسبة قصة تدريبية للقرآن"],"practice":"اقرأ النص التدريبي وحدد الجملة الدالة على الصدق، ثم اكتب تفسيرًا لا يتجاوز ما ورد.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"0a27f75b-3990-4fdb-add8-aae01ae2bef6","n":4,"title":"الكتابة","passage":"موضوع الوحدة «من القيم الإنسانية في القرآن الكريم». تناقش حصة اللغة العربية قيم الصدق والعدل والإحسان بوصفها مفاهيم أخلاقية تحتاج إلى دراسة النص القرآني من المصحف الصحيح عند الاستشهاد. وفي مثال تدريبي مستقل يعيد طالب كتابًا وجدَه إلى صاحبه ويحترم حق الآخرين في السؤال. المهارة: الكتابة. تتضمن الفقرة الكتابية جملة موضوعية وشرحًا وشاهدًا أو موقفًا وخاتمة توضح الموقف. تُراجع الأخطاء الإملائية والروابط، مع التنبيه إلى أن نصوص ضاديوم أمثلة أصلية لا تطابق بالضرورة صفحات الكتاب الوزاري.","question":"ما الذي يجعل فقرة عن «من القيم الإنسانية في القرآن الكريم» مقنعة ومترابطة؟","correct":"فكرة واضحة وشاهد صحيح ومراجعة الصياغة","wrong":["جمع كلمات بلا ترتيب","اختلاق مصدر لزيادة الإقناع","نسخ عنوان الموضوع مرات"],"practice":"اكتب فقرة من ست جمل حول «من القيم الإنسانية في القرآن الكريم» تتضمن موقفًا أصليًا وشاهدًا ورابطًا بين الجمل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"0a27f75b-3990-4fdb-add8-aae01ae2bef6","n":5,"title":"أبني لغتي","passage":"موضوع الوحدة «من القيم الإنسانية في القرآن الكريم». تناقش حصة اللغة العربية قيم الصدق والعدل والإحسان بوصفها مفاهيم أخلاقية تحتاج إلى دراسة النص القرآني من المصحف الصحيح عند الاستشهاد. وفي مثال تدريبي مستقل يعيد طالب كتابًا وجدَه إلى صاحبه ويحترم حق الآخرين في السؤال. المهارة: أبني لغتي. يُميز المتعلم في الجملة الاسمية المبتدأ والخبر ويتابع وظيفة النعت أو شبه الجملة إذا وردت، ويدرس علامات الإعراب من سياقها. تستعمل أمثلة جديدة مستقلة عن النص الوزاري، ثم يكتب الطالب صياغة صحيحة في موضوع الوحدة.","question":"ما إعراب الكلمة الأولى في المثال «الأمانةُ قيمةٌ عاليةٌ في المعاملة»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","حال منصوبة","مضاف إليه مجرور"],"practice":"حلل المبتدأ والخبر في «الأمانةُ قيمةٌ عاليةٌ في المعاملة»، ثم اكتب جملتين اسميتين أخريين عن الصدق.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"079da737-1979-4a77-94b2-1eb4fd7db842","n":1,"title":"الاستماع","passage":"موضوع الوحدة «نحن والإعلام». شاهد الطلاب خبرًا مرئيًا عن معرض للقراءة، ثم قارنوا نص الخبر بتعليق منشور على منصة اجتماعية. لاحظوا أن الخبر يذكر وقتًا ومكانًا يمكن التحقق منهما، بينما يصف التعليق الحدث برأي شخصي لا يصلح وحده دليلًا. المهارة: الاستماع. يُقرأ النص التدريبي بصوت واضح أو يعرض عبر خاصية الاستماع؛ يدون المتعلم الفكرة وتفصيلين سمعهما، ثم يقارن ما سمع بما فهم دون إضافة معلومات لم ترد. يلتزم المعلم بتيسير الإعادة وإتاحة النص المكتوب للمتعلمين عند الحاجة.","question":"ما الفكرة الرئيسة التي يجب التقاطها من الاستماع إلى نص «نحن والإعلام»؟","correct":"التمييز بين الخبر والرأي والتحقق من السياق","wrong":["الاعتماد على عدد الإعجابات","اعتبار التعليق وثيقة كاملة","حذف تاريخ الخبر"],"practice":"استمع إلى النص الأصلي التدريبي مرتين، وسجل التحقق وتفصيلين داعمين ومعلومة تحتاج تحققًا.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"079da737-1979-4a77-94b2-1eb4fd7db842","n":2,"title":"التحدث","passage":"موضوع الوحدة «نحن والإعلام». شاهد الطلاب خبرًا مرئيًا عن معرض للقراءة، ثم قارنوا نص الخبر بتعليق منشور على منصة اجتماعية. لاحظوا أن الخبر يذكر وقتًا ومكانًا يمكن التحقق منهما، بينما يصف التعليق الحدث برأي شخصي لا يصلح وحده دليلًا. المهارة: التحدث. يبدأ المتحدث بمقدمة محددة ويعرض رأيه مدعومًا بشاهد أو مثال، ثم يتيح للآخرين طرح الأسئلة ويعترف بما لم يتحقق منه. في التدريب يتكلم الطالب دقيقة واحدة عن موضوع الوحدة ويبتعد عن التعميم وأحكام الأشخاص.","question":"أي خطة مناسبة لتقديم حديث قصير حول «نحن والإعلام»؟","correct":"عرض كيفية تقييم خبر قبل مشاركته","wrong":["رفع الصوت بلا حجة","تكرار شعار دون دليل","تجنب أسئلة الجمهور"],"practice":"قدم عرضًا شفهيًا لمدة دقيقة عن «نحن والإعلام» يتضمن فكرة وشاهدًا وسؤالًا يجيب عنه زميل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"079da737-1979-4a77-94b2-1eb4fd7db842","n":3,"title":"القراءة","passage":"موضوع الوحدة «نحن والإعلام». شاهد الطلاب خبرًا مرئيًا عن معرض للقراءة، ثم قارنوا نص الخبر بتعليق منشور على منصة اجتماعية. لاحظوا أن الخبر يذكر وقتًا ومكانًا يمكن التحقق منهما، بينما يصف التعليق الحدث برأي شخصي لا يصلح وحده دليلًا. المهارة: القراءة. يحدد المتعلم الفكرة في الفقرة ثم يستخرج دليلًا من النص ويشرح علاقة السبب بالنتيجة أو قيمة القرار الموصوف. يفصل بين ما تقوله الفقرة وما قد يضيفه من معرفته، ويضع علامة على كل معلومة لا تكفي البيانات لتقريرها.","question":"أي عبارة تلخص رسالة فقرة «نحن والإعلام»؟","correct":"التمييز بين الخبر والرأي والتحقق من السياق","wrong":["الاعتماد على عدد الإعجابات","اعتبار التعليق وثيقة كاملة","حذف تاريخ الخبر"],"practice":"اقرأ النص التدريبي وحدد الجملة الدالة على التحقق، ثم اكتب تفسيرًا لا يتجاوز ما ورد.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"079da737-1979-4a77-94b2-1eb4fd7db842","n":4,"title":"الكتابة","passage":"موضوع الوحدة «نحن والإعلام». شاهد الطلاب خبرًا مرئيًا عن معرض للقراءة، ثم قارنوا نص الخبر بتعليق منشور على منصة اجتماعية. لاحظوا أن الخبر يذكر وقتًا ومكانًا يمكن التحقق منهما، بينما يصف التعليق الحدث برأي شخصي لا يصلح وحده دليلًا. المهارة: الكتابة. تتضمن الفقرة الكتابية جملة موضوعية وشرحًا وشاهدًا أو موقفًا وخاتمة توضح الموقف. تُراجع الأخطاء الإملائية والروابط، مع التنبيه إلى أن نصوص ضاديوم أمثلة أصلية لا تطابق بالضرورة صفحات الكتاب الوزاري.","question":"ما الذي يجعل فقرة عن «نحن والإعلام» مقنعة ومترابطة؟","correct":"فكرة واضحة وشاهد صحيح ومراجعة الصياغة","wrong":["جمع كلمات بلا ترتيب","اختلاق مصدر لزيادة الإقناع","نسخ عنوان الموضوع مرات"],"practice":"اكتب فقرة من ست جمل حول «نحن والإعلام» تتضمن موقفًا أصليًا وشاهدًا ورابطًا بين الجمل.","old":"DADYOOM_JO_G11_S1_OFFICIAL"},{"cid":"71517441-f388-4f1e-ae4d-ceff12317c4a","unit":"079da737-1979-4a77-94b2-1eb4fd7db842","n":5,"title":"أبني لغتي","passage":"موضوع الوحدة «نحن والإعلام». شاهد الطلاب خبرًا مرئيًا عن معرض للقراءة، ثم قارنوا نص الخبر بتعليق منشور على منصة اجتماعية. لاحظوا أن الخبر يذكر وقتًا ومكانًا يمكن التحقق منهما، بينما يصف التعليق الحدث برأي شخصي لا يصلح وحده دليلًا. المهارة: أبني لغتي. يُميز المتعلم في الجملة الاسمية المبتدأ والخبر ويتابع وظيفة النعت أو شبه الجملة إذا وردت، ويدرس علامات الإعراب من سياقها. تستعمل أمثلة جديدة مستقلة عن النص الوزاري، ثم يكتب الطالب صياغة صحيحة في موضوع الوحدة.","question":"ما إعراب الكلمة الأولى في المثال «الخبرُ واضحٌ حين تُذكر مصادره»؟","correct":"مبتدأ مرفوع","wrong":["مفعول به منصوب","حال منصوبة","مضاف إليه مجرور"],"practice":"حلل المبتدأ والخبر في «الخبرُ واضحٌ حين تُذكر مصادره»، ثم اكتب جملتين اسميتين أخريين عن التحقق.","old":"DADYOOM_JO_G11_S1_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='JO' AND c.id=r.cid
    AND g.grade_number=11 AND u.semester=1 AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'JO_G11_S1_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'JO_G11_S1_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'JO_G11_S1_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'JO_G11_S1_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_JO_G11_S1_ORIGINAL_25_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_JO_G11_S1_ORIGINAL_25_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_JO_G11_S1_ORIGINAL_25_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_JO_G11_S1_ORIGINAL_25_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'JO_G11_S1_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;